def background(grid):
    """The most frequent color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def find_divider(grid):
    """The index of the full-width single-color divider row (not the background color)."""
    bg = background(grid)
    return next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg)

def object_cells(grid, bg, divider):
    """The (row, col) cells of the moving object: not background, not on the divider row."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row)
            if v != bg and i != divider]

def move_to_line(grid, bg, line_color=8):
    """Slide the object to touch the horizontal divider, drawing a full row of line_color on its far side."""
    d = find_divider(grid)
    cells = object_cells(grid, bg, d)
    above = all(i < d for i, _ in cells)
    rows = sorted({i for i, _ in cells})
    h = rows[-1] - rows[0] + 1
    top = d - h if above else d + 1
    out = [[bg] * len(grid[0]) for _ in grid]
    out[d] = grid[d]
    for i, j in cells:
        out[top + i - rows[0]][j] = grid[i][j]
    line = top - 1 if above else top + h
    if 0 <= line < len(grid):
        out[line] = [line_color] * len(grid[0])
    return out

